// src/modules/auth/role-middleware.ts
function requireRole(...roles) {
  return async (request, reply) => {
    const user = request.user;
    if (!user || !roles.includes(user.role)) {
      return reply.status(403).send({ error: "Kh\xF4ng c\xF3 quy\u1EC1n truy c\u1EADp" });
    }
  };
}

