async function notificationRoutes(app) {
  app.addHook("preHandler", authMiddleware);
  app.get("/api/v1/notifications", async (request) => {
    const user = request.user;
    const notifications = [];
    const thirtyMinAgo = new Date(Date.now() - 30 * 6e4);
    const unrepliedRes = await db.select({ value: count() }).from(conversations).where(and(
      eq(conversations.orgId, user.orgId),
      eq(conversations.isReplied, false),
      lt(conversations.lastMessageAt, thirtyMinAgo)
    ));
    const unreplied = unrepliedRes[0].value;
    if (unreplied > 0) {
      notifications.push({
        id: "unreplied",
        type: "warning",
        priority: "high",
        title: `${unreplied} cu\u1ED9c tr\xF2 chuy\u1EC7n ch\u01B0a tr\u1EA3 l\u1EDDi`,
        detail: "C\xF3 tin nh\u1EAFn ch\u01B0a ph\u1EA3n h\u1ED3i qu\xE1 30 ph\xFAt",
        createdAt: (/* @__PURE__ */ new Date()).toISOString()
      });
    }
    const now = /* @__PURE__ */ new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const todayEnd = new Date(todayStart);
    todayEnd.setDate(todayEnd.getDate() + 1);
    const todayApts = await db.query.appointments.findMany({
      where: and(
        eq(appointments.orgId, user.orgId),
        gte(appointments.appointmentDate, todayStart),
        lt(appointments.appointmentDate, todayEnd),
        eq(appointments.status, "scheduled")
      ),
      with: { contact: { columns: { fullName: true } } },
      limit: 5
    });
    for (const apt of todayApts) {
      notifications.push({
        id: `apt-${apt.id}`,
        type: "info",
        priority: "medium",
        title: `L\u1ECBch h\u1EB9n: ${apt.contact?.fullName || "KH"}`,
        detail: `${apt.appointmentTime || ""} - ${apt.notes || "T\xE1i kh\xE1m"}`,
        createdAt: apt.appointmentDate.toISOString()
      });
    }
    const tomorrowStart = new Date(todayEnd);
    const tomorrowEnd = new Date(tomorrowStart);
    tomorrowEnd.setDate(tomorrowEnd.getDate() + 1);
    const tmrAptsRes = await db.select({ value: count() }).from(appointments).where(and(
      eq(appointments.orgId, user.orgId),
      gte(appointments.appointmentDate, tomorrowStart),
      lt(appointments.appointmentDate, tomorrowEnd),
      eq(appointments.status, "scheduled")
    ));
    const tmrApts = tmrAptsRes[0].value;
    if (tmrApts > 0) {
      notifications.push({
        id: "tmr-apts",
        type: "info",
        priority: "low",
        title: `${tmrApts} l\u1ECBch h\u1EB9n ng\xE0y mai`,
        detail: "Chu\u1EA9n b\u1ECB cho ng\xE0y mai",
        createdAt: (/* @__PURE__ */ new Date()).toISOString()
      });
    }
    const accounts = await db.query.zaloAccounts.findMany({
      where: eq(zaloAccounts.orgId, user.orgId),
      columns: { id: true, displayName: true }
    });
    for (const acc of accounts) {
      const status = zaloPool.getStatus(acc.id);
      if (status !== "connected") {
        notifications.push({
          id: `zalo-${acc.id}`,
          type: "error",
          priority: "high",
          title: `Zalo "${acc.displayName}" m\u1EA5t k\u1EBFt n\u1ED1i`,
          detail: `Tr\u1EA1ng th\xE1i: ${status}`,
          createdAt: (/* @__PURE__ */ new Date()).toISOString()
        });
      }
    }
    return { notifications };
  });
}

// src/modules/search/search-routes.ts
init_db2();
init_schema();
init_drizzle_orm();
async function searchRoutes(app) {
  app.addHook("preHandler", authMiddleware);
  app.get("/api/v1/search", async (request) => {
    const user = request.user;
    const { q = "" } = request.query;
    if (!q || q.length < 2) return { contacts: [], messages: [], appointments: [] };
    const searchTerm = q.trim();
    const pattern = `%${searchTerm}%`;
    const [contactResults, messageResults, appointmentResults] = await Promise.all([
      db.query.contacts.findMany({
        where: and(
          eq(contacts.orgId, user.orgId),
          or(
            like(contacts.fullName, pattern),
            like(contacts.phone, pattern),
            like(contacts.notes, pattern)
          )
        ),
        columns: { id: true, fullName: true, phone: true, diseaseCode: true, diseaseName: true },
        limit: 10
      }),
      db.query.messages.findMany({
        where: and(
          like(messages.content, pattern),
          // Filter by orgId through conversation join logic
          sql`EXISTS (SELECT 1 FROM ${conversations} WHERE ${conversations.id} = ${messages.conversationId} AND ${conversations.orgId} = ${user.orgId})`
        ),
        with: {
          conversation: {
            columns: { id: true },
            with: {
              contact: { columns: { fullName: true } }
            }
          }
        },
        orderBy: [desc(messages.sentAt)],
        limit: 10
      }),
      db.query.appointments.findMany({
        where: and(
          eq(appointments.orgId, user.orgId),
          or(
            like(appointments.notes, pattern),
            // Subquery for contact name match since Drizzle findMany 'where' doesn't support easy join filtering in SQLite yet
            sql`EXISTS (SELECT 1 FROM ${contacts} WHERE ${contacts.id} = ${appointments.contactId} AND ${contacts.fullName} LIKE ${pattern})`
          )
        ),
        with: {
          contact: { columns: { fullName: true } }
        },
        limit: 10
      })
    ]);
    return { contacts: contactResults, messages: messageResults, appointments: appointmentResults };
  });
}

