// src/modules/analytics/reports/conversion-funnel.ts
init_db2();
init_schema();
init_drizzle_orm();
var STAGE_ORDER = ["new", "contacted", "interested", "converted", "lost"];
async function getConversionFunnel(orgId, from, to) {
  const startDate = new Date(from);
  const endDate = new Date(to);
  endDate.setDate(endDate.getDate() + 1);
  const groups = await db.select({
    status: contacts.status,
    count: count()
  }).from(contacts).where(and(
    eq(contacts.orgId, orgId),
    gte(contacts.createdAt, startDate),
    lt(contacts.createdAt, endDate),
    ne(contacts.status, "")
  )).groupBy(contacts.status);
  const countMap = {};
  let total = 0;
  for (const g of groups) {
    const s = g.status ?? "unknown";
    countMap[s] = g.count;
    total += g.count;
  }
  const stages = STAGE_ORDER.map((status) => ({
    status,
    count: countMap[status] ?? 0,
    rate: total > 0 ? Math.round((countMap[status] ?? 0) / total * 1e3) / 10 : 0
  }));
  const avgResult = await db.select({
    avgSeconds: sql`AVG(CAST((julianday(${contacts.updatedAt}) - julianday(${contacts.createdAt})) * 86400 AS REAL))`
  }).from(contacts).where(and(
    eq(contacts.orgId, orgId),
    eq(contacts.status, "converted"),
    gte(contacts.createdAt, startDate),
    lt(contacts.createdAt, endDate)
  ));
  const avgDays = avgResult[0]?.avgSeconds ? avgResult[0].avgSeconds / 86400 : null;
  return {
    stages,
    totalContacts: total,
    avgConversionDays: avgDays ? Math.round(avgDays * 10) / 10 : null
  };
}

// src/modules/analytics/reports/team-performance.ts
init_db2();
init_schema();
init_drizzle_orm();
init_drizzle_orm();
async function getTeamPerformance(orgId, from, to) {
  const startDate = new Date(from);
  const endDate = new Date(to);
  endDate.setDate(endDate.getDate() + 1);
  const orgUsersList = await db.query.users.findMany({
    where: and(eq(users.orgId, orgId), eq(users.isActive, true)),
    columns: { id: true, fullName: true }
  });
  if (!orgUsersList.length) return { users: [] };
  const userIds = orgUsersList.map((u) => u.id);
  const [msgRows, convertedRows, aptRows, rtRows] = await Promise.all([
    // Messages sent per user (replied_by_user_id)
    db.select({
      userId: messages.repliedByUserId,
      cnt: count()
    }).from(messages).innerJoin(conversations, eq(conversations.id, messages.conversationId)).where(and(
      eq(conversations.orgId, orgId),
      eq(messages.senderType, "self"),
      isNotNull(messages.repliedByUserId),
      inArray(messages.repliedByUserId, userIds),
      gte(messages.sentAt, startDate),
      lt(messages.sentAt, endDate)
    )).groupBy(messages.repliedByUserId),
    // Contacts converted per user
    db.select({
      assignedUserId: contacts.assignedUserId,
      cnt: count()
    }).from(contacts).where(and(
      eq(contacts.orgId, orgId),
      eq(contacts.status, "converted"),
      isNotNull(contacts.assignedUserId),
      inArray(contacts.assignedUserId, userIds),
      gte(contacts.updatedAt, startDate),
      lt(contacts.updatedAt, endDate)
    )).groupBy(contacts.assignedUserId),
    // Appointments completed per user
    db.select({
      assignedUserId: appointments.assignedUserId,
      cnt: count()
    }).from(appointments).where(and(
      eq(appointments.orgId, orgId),
      eq(appointments.status, "completed"),
      isNotNull(appointments.assignedUserId),
      inArray(appointments.assignedUserId, userIds),
      gte(appointments.appointmentDate, startDate),
      lt(appointments.appointmentDate, endDate)
    )).groupBy(appointments.assignedUserId),
    // Avg response time from DailyMessageStat
    db.select({
      userId: dailyMessageStats.userId,
      avgRt: sql`AVG(${dailyMessageStats.avgResponseTimeSeconds})`.as("avgRt")
    }).from(dailyMessageStats).where(and(
      eq(dailyMessageStats.orgId, orgId),
      isNotNull(dailyMessageStats.userId),
      inArray(dailyMessageStats.userId, userIds),
      gte(dailyMessageStats.statDate, startDate),
      lt(dailyMessageStats.statDate, endDate)
    )).groupBy(dailyMessageStats.userId)
  ]);
  const msgMap = new Map(msgRows.map((r) => [r.userId, r.cnt]));
  const convMap = new Map(convertedRows.map((r) => [r.assignedUserId, r.cnt]));
  const aptMap = new Map(aptRows.map((r) => [r.assignedUserId, r.cnt]));
  const rtMap = new Map(rtRows.map((r) => [r.userId, r.avgRt]));
  const resultUsers = orgUsersList.map((u) => ({
    userId: u.id,
    fullName: u.fullName,
    messagesSent: msgMap.get(u.id) ?? 0,
    contactsConverted: convMap.get(u.id) ?? 0,
    appointmentsCompleted: aptMap.get(u.id) ?? 0,
    avgResponseTime: rtMap.get(u.id) ?? null
  }));
  resultUsers.sort((a, b) => b.contactsConverted - a.contactsConverted);
  return { users: resultUsers };
}

// src/modules/analytics/reports/response-time.ts
init_db2();
init_schema();
init_drizzle_orm();
async function getResponseTimeAnalysis(orgId, from, to) {
  const fromDate = new Date(from);
  const toDate = new Date(to);
  toDate.setHours(23, 59, 59, 999);
  const [dailyRows, overallRows, userRows] = await Promise.all([
    // Daily avg
    db.select({
      statDate: dailyMessageStats.statDate,
      avgRt: sql`AVG(${dailyMessageStats.avgResponseTimeSeconds})`.as("avgRt")
    }).from(dailyMessageStats).where(and(
      eq(dailyMessageStats.orgId, orgId),
      gte(dailyMessageStats.statDate, fromDate),
      lte(dailyMessageStats.statDate, toDate),
      isNotNull(dailyMessageStats.avgResponseTimeSeconds)
    )).groupBy(dailyMessageStats.statDate).orderBy(asc(dailyMessageStats.statDate)),
    // Overall avg
    db.select({
      avgRt: sql`AVG(${dailyMessageStats.avgResponseTimeSeconds})`
    }).from(dailyMessageStats).where(and(
      eq(dailyMessageStats.orgId, orgId),
      gte(dailyMessageStats.statDate, fromDate),
      lte(dailyMessageStats.statDate, toDate),
      isNotNull(dailyMessageStats.avgResponseTimeSeconds)
    )),
    // Per-user avg
    db.select({
      userId: dailyMessageStats.userId,
      fullName: users.fullName,
      avgRt: sql`AVG(${dailyMessageStats.avgResponseTimeSeconds})`.as("avgRt")
    }).from(dailyMessageStats).innerJoin(users, eq(users.id, dailyMessageStats.userId)).where(and(
      eq(dailyMessageStats.orgId, orgId),
      gte(dailyMessageStats.statDate, fromDate),
      lte(dailyMessageStats.statDate, toDate),
      isNotNull(dailyMessageStats.avgResponseTimeSeconds)
    )).groupBy(dailyMessageStats.userId, users.fullName).orderBy(asc(sql`avgRt`))
  ]);
  return {
    daily: dailyRows.map((r) => ({
      date: typeof r.statDate === "string" ? r.statDate : r.statDate.toISOString().split("T")[0],
      avgSeconds: Math.round(r.avgRt)
    })),
    overall: overallRows[0]?.avgRt ? Math.round(overallRows[0].avgRt) : null,
    byUser: userRows.map((r) => ({
      userId: r.userId,
      fullName: r.fullName,
      avgSeconds: Math.round(r.avgRt)
    }))
  };
}

// src/modules/analytics/reports/custom-report.ts
init_db2();
init_drizzle_orm();
async function executeCustomReport(orgId, config2) {
  const { from, to } = config2.dateRange;
  const startDate = new Date(from);
  const endDate = new Date(to);
  endDate.setDate(endDate.getDate() + 1);
  const datasets = [];
  let labels = [];
  for (const metric of config2.metrics) {
    const result = await queryMetric(orgId, metric, config2.groupBy, startDate, endDate, config2.filters);
    if (!labels.length) labels = result.labels;
    datasets.push({ metric, data: result.data });
  }
  return { labels, datasets };
}
async function queryMetric(orgId, metric, groupBy, gte2, lt3, filters) {
  switch (metric) {
    case "messages_sent":
    case "messages_received":
      return queryMessageMetric(orgId, metric, groupBy, gte2, lt3, filters);
    case "contacts_new":
      return queryContactMetric(orgId, "new", groupBy, gte2, lt3, filters);
    case "contacts_converted":
      return queryContactMetric(orgId, "converted", groupBy, gte2, lt3, filters);
    case "appointments":
      return queryAppointmentMetric(orgId, groupBy, gte2, lt3);
    case "avg_response_time":
      return queryResponseTimeMetric(orgId, groupBy, gte2, lt3, filters);
    default:
      return { labels: [], data: [] };
  }
}
async function queryMessageMetric(orgId, metric, groupBy, gte2, lt3, filters) {
  const senderType = metric === "messages_sent" ? "self" : "contact";
  const dateExpr = groupByDateExpr(groupBy, "m.sent_at");
  if (groupBy === "user") {
    const rows2 = db.all(sql`
      SELECT u.full_name AS label, COUNT(*) AS cnt
      FROM messages m
      JOIN conversations c ON c.id = m.conversation_id
      LEFT JOIN users u ON u.id = m.replied_by_user_id
      WHERE c.org_id = ${orgId} AND m.sender_type = ${senderType}
        AND m.sent_at >= ${gte2.getTime()} AND m.sent_at < ${lt3.getTime()}
      GROUP BY u.full_name ORDER BY cnt DESC
    `);
    return {
      labels: rows2.map((r) => r.label ?? "N/A"),
      data: rows2.map((r) => Number(r.cnt))
    };
  }
  if (groupBy === "source") {
    const rows2 = db.all(sql`
      SELECT COALESCE(ct.source, 'N/A') AS label, COUNT(*) AS cnt
      FROM messages m
      JOIN conversations c ON c.id = m.conversation_id
      LEFT JOIN contacts ct ON ct.id = c.contact_id
      WHERE c.org_id = ${orgId} AND m.sender_type = ${senderType}
        AND m.sent_at >= ${gte2.getTime()} AND m.sent_at < ${lt3.getTime()}
      GROUP BY ct.source ORDER BY cnt DESC
    `);
    return {
      labels: rows2.map((r) => String(r.label)),
      data: rows2.map((r) => Number(r.cnt))
    };
  }
  const rows = db.all(sql`
    SELECT ${sql.raw(dateExpr)} AS label, COUNT(*) AS cnt
    FROM messages m
    JOIN conversations c ON c.id = m.conversation_id
    WHERE c.org_id = ${orgId} AND m.sender_type = ${senderType}
      AND m.sent_at >= ${gte2.getTime()} AND m.sent_at < ${lt3.getTime()}
    GROUP BY label ORDER BY label ASC
  `);
  return {
    labels: rows.map((r) => String(r.label)),
    data: rows.map((r) => Number(r.cnt))
  };
}
async function queryContactMetric(orgId, type, groupBy, gte2, lt3, filters) {
  const dateCol = type === "new" ? "created_at" : "updated_at";
  const statusCond = type === "converted" ? sql`AND status = 'converted'` : sql``;
  const sourceCond = filters?.source ? sql`AND source = ${filters.source}` : sql``;
  if (groupBy === "user") {
    const rows2 = db.all(sql`
      SELECT COALESCE(u.full_name, 'Chưa gán') AS label, COUNT(*) AS cnt
      FROM contacts c LEFT JOIN users u ON u.id = c.assigned_user_id
      WHERE c.org_id = ${orgId} AND c.${sql.raw(dateCol)} >= ${gte2.getTime()} AND c.${sql.raw(dateCol)} < ${lt3.getTime()}
        ${statusCond} ${sourceCond}
      GROUP BY u.full_name ORDER BY cnt DESC
    `);
    return { labels: rows2.map((r) => String(r.label)), data: rows2.map((r) => Number(r.cnt)) };
  }
  if (groupBy === "source") {
    const rows2 = db.all(sql`
      SELECT COALESCE(source, 'N/A') AS label, COUNT(*) AS cnt
      FROM contacts WHERE org_id = ${orgId} AND ${sql.raw(dateCol)} >= ${gte2.getTime()} AND ${sql.raw(dateCol)} < ${lt3.getTime()}
        ${statusCond}
      GROUP BY source ORDER BY cnt DESC
    `);
    return { labels: rows2.map((r) => String(r.label)), data: rows2.map((r) => Number(r.cnt)) };
  }
  const dateExpr = groupByDateExpr(groupBy, dateCol);
  const rows = db.all(sql`
    SELECT ${sql.raw(dateExpr)} AS label, COUNT(*) AS cnt
    FROM contacts WHERE org_id = ${orgId} AND ${sql.raw(dateCol)} >= ${gte2.getTime()} AND ${sql.raw(dateCol)} < ${lt3.getTime()}
      ${statusCond} ${sourceCond}
    GROUP BY label ORDER BY label ASC
  `);
  return { labels: rows.map((r) => String(r.label)), data: rows.map((r) => Number(r.cnt)) };
}
async function queryAppointmentMetric(orgId, groupBy, gte2, lt3) {
  if (groupBy === "user") {
    const rows2 = db.all(sql`
      SELECT COALESCE(u.full_name, 'Chưa gán') AS label, COUNT(*) AS cnt
      FROM appointments a LEFT JOIN users u ON u.id = a.assigned_user_id
      WHERE a.org_id = ${orgId} AND a.appointment_date >= ${gte2.getTime()} AND a.appointment_date < ${lt3.getTime()}
      GROUP BY u.full_name ORDER BY cnt DESC
    `);
    return { labels: rows2.map((r) => String(r.label)), data: rows2.map((r) => Number(r.cnt)) };
  }
  const dateExpr = groupByDateExpr(groupBy, "appointment_date");
  const rows = db.all(sql`
    SELECT ${sql.raw(dateExpr)} AS label, COUNT(*) AS cnt
    FROM appointments WHERE org_id = ${orgId} AND appointment_date >= ${gte2.getTime()} AND appointment_date < ${lt3.getTime()}
    GROUP BY label ORDER BY label ASC
  `);
  return { labels: rows.map((r) => String(r.label)), data: rows.map((r) => Number(r.cnt)) };
}
async function queryResponseTimeMetric(orgId, groupBy, gte2, lt3, filters) {
  if (groupBy === "user") {
    const rows2 = db.all(sql`
      SELECT u.full_name AS label, AVG(d.avg_response_time_seconds) AS avg_rt
      FROM daily_message_stats d JOIN users u ON u.id = d.user_id
      WHERE d.org_id = ${orgId} AND d.stat_date >= ${gte2.toISOString().split("T")[0]} AND d.stat_date < ${lt3.toISOString().split("T")[0]}
        AND d.avg_response_time_seconds IS NOT NULL
      GROUP BY u.full_name ORDER BY avg_rt ASC
    `);
    return { labels: rows2.map((r) => String(r.label)), data: rows2.map((r) => Math.round(Number(r.avg_rt))) };
  }
  const dateExpr = groupByDateExpr(groupBy, "stat_date");
  const rows = db.all(sql`
    SELECT ${sql.raw(dateExpr)} AS label, AVG(avg_response_time_seconds) AS avg_rt
    FROM daily_message_stats
    WHERE org_id = ${orgId} AND stat_date >= ${gte2.toISOString().split("T")[0]} AND stat_date < ${lt3.toISOString().split("T")[0]}
      AND avg_response_time_seconds IS NOT NULL
    GROUP BY label ORDER BY label ASC
  `);
  return { labels: rows.map((r) => String(r.label)), data: rows.map((r) => Math.round(Number(r.avg_rt))) };
}
function groupByDateExpr(groupBy, col) {
  const dateCol = `datetime(${col} / 1000, 'unixepoch')`;
  switch (groupBy) {
    case "week":
      return `strftime('%Y-W%W', ${dateCol})`;
    case "month":
      return `strftime('%Y-%m', ${dateCol})`;
    default:
      return `strftime('%Y-%m-%d', ${dateCol})`;
  }
}

