init_logger2();
async function triggerZapierWebhook(orgId, config2) {
  const { webhookUrl } = config2;
  if (!webhookUrl) {
    return { direction: "export", recordCount: 0, status: "failed", errorMessage: "Missing webhookUrl" };
  }
  try {
    const parsed = new URL(webhookUrl);
    if (parsed.protocol !== "https:") {
      return { direction: "export", recordCount: 0, status: "failed", errorMessage: "webhookUrl must use HTTPS" };
    }
    const blocked = /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|169\.254\.)/;
    if (blocked.test(parsed.hostname)) {
      return { direction: "export", recordCount: 0, status: "failed", errorMessage: "webhookUrl target is not allowed" };
    }
  } catch {
    return { direction: "export", recordCount: 0, status: "failed", errorMessage: "Invalid webhookUrl" };
  }
  try {
    const since = new Date(Date.now() - 24 * 60 * 60 * 1e3);
    const list = await db.query.contacts.findMany({
      where: and(eq(contacts.orgId, orgId), gte(contacts.createdAt, since)),
      orderBy: [desc(contacts.createdAt)],
      limit: 100
    });
    const payload = {
      event: "contacts.sync",
      orgId,
      timestamp: (/* @__PURE__ */ new Date()).toISOString(),
      count: list.length,
      contacts: list.map((c) => ({
        id: c.id,
        fullName: c.fullName,
        phone: c.phone,
        email: c.email,
        source: c.source,
        status: c.status,
        createdAt: c.createdAt?.toISOString() ?? ""
      }))
    };
    const response = await fetch(webhookUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(15e3)
    });
    if (!response.ok) {
      const body = await response.text();
      logger.error("[zapier-webhook] Error:", body);
      return { direction: "export", recordCount: 0, status: "failed", errorMessage: `Zapier ${response.status}: ${body.slice(0, 200)}` };
    }
    logger.info(`[zapier-webhook] Sent ${list.length} contacts to Zapier`);
    return { direction: "export", recordCount: list.length, status: "success" };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return { direction: "export", recordCount: 0, status: "failed", errorMessage: msg };
  }
}

// src/modules/integrations/sync-engine.ts
init_dist_node();
async function runSync(integration) {
  let result;
  try {
    const cfg = integration.config;
    switch (integration.type) {
      case "google_sheets":
        result = await syncGoogleSheets(integration.orgId, cfg);
        break;
      case "telegram":
        result = await sendTelegramNotification(integration.orgId, cfg);
        break;
      case "facebook":
        result = await importFacebookLeads(integration.orgId, cfg);
        break;
      case "zapier":
        result = await triggerZapierWebhook(integration.orgId, cfg);
        break;
      default:
        result = { direction: "export", recordCount: 0, status: "failed", errorMessage: `Unknown type: ${integration.type}` };
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logger.error(`[sync-engine] ${integration.type} sync failed:`, msg);
    result = { direction: "export", recordCount: 0, status: "failed", errorMessage: msg };
  }
  try {
    const logId = v4_default();
    await db.insert(syncLogs).values({
      id: logId,
      integrationId: integration.id,
      direction: result.direction,
      recordCount: result.recordCount,
      status: result.status,
      errorMessage: result.errorMessage ?? null
    });
    await db.update(integrations).set({ lastSyncAt: /* @__PURE__ */ new Date(), updatedAt: /* @__PURE__ */ new Date() }).where(eq(integrations.id, integration.id));
    return await db.query.syncLogs.findFirst({ where: eq(syncLogs.id, logId) });
  } catch (dbErr) {
    logger.error(`[sync-engine] Failed to persist sync log:`, dbErr);
    return { ...result, integrationId: integration.id };
  }
}

