// src/modules/ai/providers/anthropic.ts
async function generateWithAnthropic(baseUrl, apiKey, model, system, prompt) {
  const url = `${baseUrl}/v1/messages`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 3e4);
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": apiKey,
        authorization: `Bearer ${apiKey}`,
        "anthropic-version": "2023-06-01"
      },
      body: JSON.stringify({
        model,
        max_tokens: 600,
        system,
        messages: [{ role: "user", content: prompt }]
      }),
      signal: controller.signal
    });
    if (!response.ok) {
      const body = await response.text().catch(() => "");
      throw new Error(`Anthropic request failed (${response.status}): ${body}`);
    }
    const data = await response.json();
    const text2 = data.content?.find((item) => item.type === "text")?.text?.trim();
    if (!text2) throw new Error("Anthropic returned empty content");
    return text2;
  } finally {
    clearTimeout(timeout);
  }
}

// src/modules/ai/providers/gemini.ts
async function generateWithGemini(baseUrl, apiKey, model, system, prompt) {
  const url = `${baseUrl}/v1beta/models/${encodeURIComponent(model)}:generateContent?key=${encodeURIComponent(apiKey)}`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 3e4);
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        systemInstruction: { parts: [{ text: system }] },
        contents: [{ role: "user", parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.4, maxOutputTokens: 600 }
      }),
      signal: controller.signal
    });
    if (!response.ok) {
      const status = response.status;
      throw new Error(`Gemini request failed with status ${status}`);
    }
    const data = await response.json();
    const text2 = data.candidates?.[0]?.content?.parts?.map((part) => part.text || "").join("").trim();
    if (!text2) throw new Error("Gemini returned empty content");
    return text2;
  } finally {
    clearTimeout(timeout);
  }
}

// src/modules/ai/providers/openai-compat.ts
async function generateWithOpenaiCompat(url, apiKey, model, system, prompt) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 3e4);
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model,
        messages: [
          { role: "system", content: system },
          { role: "user", content: prompt }
        ],
        max_tokens: 600
      }),
      signal: controller.signal
    });
    if (!response.ok) {
      const status = response.status;
      throw new Error(`OpenAI-compat request failed with status ${status}`);
    }
    const data = await response.json();
    const text2 = data.choices?.[0]?.message?.content?.trim();
    if (!text2) throw new Error("OpenAI-compat returned empty content");
    return text2;
  } finally {
    clearTimeout(timeout);
  }
}

